function saveVehicle(){
  const g=id=>document.getElementById(id)?.value.trim()||'';
  const model=g('nv-model'), version=g('nv-version'), price=+g('nv-price');
  if(!model||!version||!price){toast('Complete modelo, versión y precio');return}
  const brand=g('nv-brand')||'Range Rover';
  const v={id:(model.slice(0,2)+'-'+String(Math.floor(100+Math.random()*899))).toUpperCase(),
    brand, model, version, year:+g('nv-year')||2027, price, cost:+g('nv-cost')||Math.round(price*0.76),
    color:g('nv-color')||'Fuji White', hex:'#8a8a85', stock:+g('nv-stock')||1, condition:'Nuevo',
    days:0, engine:g('nv-engine')||'Por definir', image:'hero', km:0, stage:+g('nv-stage')};
  vehicles.unshift(v);
  closeModal(); render();
  toast(model+' '+version+' ya se puede cotizar');
}
function openVehicle(id){const v=vehicles.find(v=>v.id===id);openModal(`<div class="drawer-eyebrow">${v.condition.toUpperCase()} COLLECTION · ${v.id}</div><div class="vehicle-detail-art"><span>${v.brand.toUpperCase()}</span><strong>${v.id.split('-')[1]}</strong><i style="background:${v.hex}"></i></div><h2 class="drawer-title">${v.model}</h2><p class="drawer-subtitle">${v.version} · ${v.year}</p><div class="detail-price">${money(v.price)}<small>Precio de referencia antes de impuestos</small></div><div class="detail-grid vehicle-details"><div><small>MOTORIZACIÓN</small><strong>${v.engine}</strong></div><div><small>COLOR EXTERIOR</small><strong>${v.color}</strong></div><div><small>DISPONIBILIDAD</small><strong>${v.stock} unidades</strong></div><div><small>EN INVENTARIO</small><strong>${v.days} días</strong></div><div><small>KILOMETRAJE</small><strong>${v.km?new Intl.NumberFormat('es').format(v.km)+' km':'0 km'}</strong></div>${canCost()?`<div><small>COSTO DE REFERENCIA</small><strong>${money(v.cost)}</strong></div>`:''}</div>${logisticsTrack(v)}${button('Configurar propuesta','vehicle-to-quote:'+v.id,'primary','arrow')}<div class="detail-section"><h3>Clientes interesados</h3>${state.clients.filter(c=>c.interest===v.model).map(c=>`<button class="matching-client" data-client="${c.id}">${avatar(c)}<span><strong>${esc(c.name)}</strong><small>${c.stage}</small></span>${ic('arrow')}</button>`).join('')||'<p class="muted">Aún no hay intereses asociados a este modelo.</p>'}</div>`)}
function openQuote(id){const q=state.quotes.find(q=>q.id===id),c=state.clients.find(c=>c.id===q.clientId),d=calcQuote(q);openModal(`<div class="drawer-eyebrow">PROPUESTA COMERCIAL · ${q.id}</div><h2 class="drawer-title">${esc(c.name)}</h2><p class="drawer-subtitle">${d.v.model} · ${d.v.version}</p><div class="quote-detail-status">${statusTag(q.status)}<span>Vigente hasta 6 oct 2026</span></div><div class="detail-price">${money(d.total)}<small>Inversión total · incluye impuesto ilustrativo del 7%</small></div><div class="summary-lines"><div><span>Vehículo</span><strong>${money(d.v.price)}</strong></div>${d.extras.map(a=>`<div><span>${a.name}</span><strong>${money(a.price)}</strong></div>`).join('')}<div><span>Descuento</span><strong>${money(d.discount)}</strong></div><div><span>Impuesto demo</span><strong>${money(d.tax)}</strong></div></div><div class="drawer-actions"><button class="btn primary" data-preview-saved="${id}">${ic('file')} Presentar propuesta</button><button class="btn secondary" data-edit-quote="${id}">Editar</button></div><div class="detail-section"><h3>Avance de la propuesta</h3><label class="form-label">Estado<select class="form-input" data-quote-status="${id}" ${q.status==='Por aprobar'&&!canCost()?'disabled':''}>${['Borrador','Enviada','En negociación','Por aprobar','Aceptada','No aceptada'].map(s=>`<option ${q.status===s?'selected':''}>${s}</option>`).join('')}</select></label>${q.status==='Por aprobar'&&canCost()?`<button class="btn primary" style="margin-top:16px" data-approve="${id}">${ic('check')} Aprobar condiciones</button>`:''}${canCost()?`<div class="margin-box ${d.margin<22?'warning':''}" style="margin-top:20px"><div><span>Margen neto</span><strong>${d.margin.toFixed(1)}%</strong></div><p>Objetivo comercial: 22% · sin impuestos</p></div>`:''}</div><div class="timeline-item"><i></i><strong>Propuesta ${q.revision>1?'actualizada · revisión '+q.revision:'creada'}</strong><p>Asesora: Gerencia</p><small>${q.date}</small></div>`)}
function newClient(stage='Contacto'){openModal(`<div class="drawer-eyebrow">UNA NUEVA RELACIÓN</div><h2 class="drawer-title">Cada historia empieza<br>con una conversación.</h2><form id="new-client-form" class="entry-form"><label>Nombre completo<input name="name" required maxlength="80" placeholder="Nombre y apellido"></label><label>Empresa<input name="company" maxlength="80" placeholder="Empresa o cliente particular"></label><div class="form-columns"><label>Correo electrónico<input name="email" type="email" required placeholder="nombre@example.com"></label><label>Teléfono<input name="phone" type="tel" required placeholder="+507"></label></div><label>Modelo de interés<select name="vehicle">${vehicles.map(v=>`<option value="${v.id}">${v.model} · ${v.version}</option>`).join('')}</select></label><div class="form-columns"><label>Origen<select name="source"><option>Showroom</option><option>Web</option><option>Referido</option><option>Feria</option><option>Instagram</option></select></label><label>Etapa<select name="stage">${stages.map(s=>`<option ${s===stage?'selected':''}>${s}</option>`).join('')}</select></label></div><label>Primera conversación<textarea name="note" rows="3" placeholder="¿Qué es importante para este cliente?"></textarea></label><button class="btn primary" type="submit">Crear oportunidad ${ic('arrow')}</button></form>`)}
function logCall(id){const c=state.clients.find(c=>c.id===id);openModal(`<div class="drawer-eyebrow">UN CONTACTO QUE CUENTA</div><h2 class="drawer-title">Conversación con<br>${esc(c.name)}</h2><form id="log-call-form" data-client-id="${id}" class="entry-form"><label>Resultado<select name="result"><option>Conversación realizada</option><option>Volver a llamar</option><option>Visita confirmada</option><option>Interés en propuesta</option></select></label><label>¿Qué conversaron?<textarea name="note" required rows="5" placeholder="Registra los detalles y el siguiente paso…"></textarea></label><label class="checkbox-label"><input type="checkbox" name="followup" checked> Añadir seguimiento a mi agenda</label><button class="btn primary" type="submit">Guardar conversación ${ic('check')}</button></form>`)}
function showSearch(){openModal(`<div class="command-input">${ic('search')}<input id="global-query" placeholder="Busca clientes, vehículos o propuestas…" aria-label="Búsqueda global" autocomplete="off"></div><div id="search-results">${searchResults('')}</div><div class="command-footer">ESC para cerrar <span>Todo tu espacio, a una búsqueda.</span></div>`,'search-modal');document.getElementById('global-query').focus()}
function searchResults(query){const text=query.toLowerCase();const cs=state.clients.filter(c=>`${c.name} ${c.interest}`.toLowerCase().includes(text)).slice(0,4);const vs=vehicles.filter(v=>`${v.model} ${v.id}`.toLowerCase().includes(text)).slice(0,3);const qs=state.quotes.filter(q=>q.id.toLowerCase().includes(text)).slice(0,2);return `<div class="search-group"><span>CLIENTES</span>${cs.map(c=>`<button data-client="${c.id}">${avatar(c)}<span><strong>${esc(c.name)}</strong><small>${c.interest}</small></span>${ic('arrow')}</button>`).join('')}</div><div class="search-group"><span>COLECCIÓN</span>${vs.map(v=>`<button data-vehicle="${v.id}">${ic('car')}<span><strong>${v.model}</strong><small>${v.version}</small></span><b>${money(v.price)}</b></button>`).join('')}</div><div class="search-group"><span>PROPUESTAS</span>${qs.map(q=>`<button data-quote="${q.id}">${ic('file')}<strong>${q.id}</strong>${statusTag(q.status)}</button>`).join('')}</div>${!cs.length&&!vs.length&&!qs.length?empty('Prueba con un nombre, modelo o número de propuesta.'):''}`}
function showAssistant(){openModal(`<div class="drawer-eyebrow">PRESTIGE INTELLIGENCE</div><div class="assistant-orb">${ic('spark')}</div><h2 class="drawer-title">Una mejor pregunta.<br>Una mejor decisión.</h2><p class="assistant-intro">Explora tu operación a partir de los datos de este escenario.</p><div id="assistant-messages"><div class="assistant-message">¿Qué te gustaría entender del negocio?</div></div><div class="suggested-prompts">${['¿Qué modelo genera más ingresos?','¿Dónde hay una oportunidad de venta?','¿Cómo está el margen?'].map(t=>`<button data-prompt="${t}">${t} ${ic('arrow')}</button>`).join('')}</div><form id="assistant-form"><input name="question" aria-label="Pregunta a Prestige Intelligence" placeholder="Pregunta sobre tu negocio…" required><button class="icon-btn" aria-label="Analizar pregunta">${ic('send')}</button></form><p class="assistant-footnote">Análisis guiado de demostración · Respuestas calculadas con datos locales.</p>`)}
function assistantAnswer(question){const node=document.getElementById('assistant-messages');if(!node)return;const sales=getSales(2026,-1),rev=sales.reduce((a,x)=>a+x.price,0);let body,source;const t=question.toLowerCase();if(/margen|rentabil|costo/.test(t)){body=canCost()?`El margen comercial acumulado es <strong>${((1-sales.reduce((a,x)=>a+x.cost,0)/rev)*100).toFixed(1)}%</strong>, por encima de la meta del 22%.<br><br>Se calcula como (ingresos − costo) ÷ ingresos. Los impuestos no forman parte de este indicador.`:'Tu perfil de Ventas no tiene acceso a costos ni márgenes. Puedes explorar modelos, clientes y oportunidades.';source=canCost()?`${sales.length} entregas · Enero–septiembre 2026`:'Acceso según perfil de demostración'}else if(/oportun|inventario|velar|cliente/.test(t)){body=`El <strong>Range Rover Velar</strong> lleva 76 días en inventario. <strong>Camila Herrera</strong> está interesada en este modelo.<br><br>Preparar una propuesta conecta un interés existente con una unidad disponible.<button class="btn primary" data-action="insight-quote">Preparar propuesta ${ic('arrow')}</button>`;source='Inventario VL-032 · Cliente Camila Herrera'}else if(/modelo|ingreso|venta|vend|mejor/.test(t)){const top=vehicles.slice(0,6).map(v=>({v,total:sales.filter(s=>s.model===v.model).reduce((a,x)=>a+x.price,0)})).sort((a,b)=>b.total-a.total)[0];body=`<strong>${top.v.model}</strong> lidera los ingresos con <strong>${money(top.total)}</strong>, el ${(top.total/rev*100).toFixed(1)}% del total del período.<br><br>Son ${sales.filter(s=>s.model===top.v.model).length} entregas registradas. Puedes abrir el reporte para ver el detalle.<button class="text-btn" data-action="insights-close">Explorar inteligencia comercial ${ic('arrow')}</button>`;source=`${sales.length} entregas · Enero–septiembre 2026`}else{body='Puedo ayudarte a explorar ingresos por modelo, oportunidades de inventario y margen comercial. Prueba con una de las preguntas sugeridas.';source='Temas disponibles en este prototipo'}node.insertAdjacentHTML('beforeend',`<div class="user-message">${esc(question)}</div><div class="assistant-message">${body}<div class="answer-source">${ic('file')} ${source}</div></div>`);node.lastElementChild.scrollIntoView({behavior:'smooth',block:'nearest'})}
function showDocument(q=draft,id=editingQuote||'DPM-PREVIEW'){const d=calcQuote(q),c=state.clients.find(c=>c.id===q.clientId);openModal(`<div class="document-toolbar"><span>Cotización lista para el cliente<small>${d.v.model} · ${money(d.total)} · ${q.term||60} meses</small></span><button class="btn primary" data-action="print">${ic('download')} Generar PDF</button></div><article class="proposal-document"><div class="document-header"><span class="document-brand">PRESTIGE<small>DISTRIBUIDORA DAVID PRESTIGE MOTORS</small></span><span>PROPUESTA PRIVADA<br>${id}<br>21 · 09 · 2026</span></div><div class="document-hero"><img src="./assets/collection-concept.png" alt="Colección conceptual Prestige"><div><span>PREPARADA PARA ${esc(c.name.toUpperCase())}</span><h2>El próximo capítulo<br>lleva tu nombre.</h2></div></div><div class="document-content"><div class="document-model"><div><span>SU SELECCIÓN</span><h3>${d.v.model}</h3><p>${d.v.version} · ${d.v.year} · ${d.paint.name}</p></div><strong>${money(d.v.price)}</strong></div>${d.paint.price?`<div class="document-line"><span>Pintura ${d.paint.name}</span><strong>${money(d.paint.price)}</strong></div>`:''}${d.trim.price?`<div class="document-line"><span>Tapicería ${d.trim.name}</span><strong>${money(d.trim.price)}</strong></div>`:''}${d.wheel.price?`<div class="document-line"><span>Rines ${d.wheel.name}</span><strong>${money(d.wheel.price)}</strong></div>`:''}${d.extras.map(a=>`<div class="document-line"><span>${a.name}</span><strong>${money(a.price)}</strong></div>`).join('')}${d.discount?`<div class="document-line"><span>Beneficio comercial</span><strong>−${money(d.discount)}</strong></div>`:''}<div class="document-line"><span>Impuesto ilustrativo · 7%</span><strong>${money(d.tax)}</strong></div><div class="document-total"><span>Su inversión total</span><strong>${money(d.total)}</strong></div><div class="document-spec"><div><small>COLOR EXTERIOR</small><strong>${d.paint.name}</strong></div><div><small>TAPICERÍA</small><strong>${d.trim.name}</strong></div><div><small>RINES</small><strong>${d.wheel.name}</strong></div><div><small>MOTORIZACIÓN</small><strong>${d.v.engine}</strong></div><div><small>PERSONALIZACIÓN</small><strong>${d.extras.length?d.extras.map(a=>a.name).join(' · '):'Configuración de fábrica'}</strong></div><div><small>ENTREGA ESTIMADA</small><strong>${diasEntrega(etapaUnidad(d.v))===0?'Disponible ahora':'En '+diasEntrega(etapaUnidad(d.v))+' días'}</strong></div></div><div class="document-finance"><div><small>ABONO INICIAL · ${q.deposit??30}%</small><strong>${money(d.down)}</strong></div><div><small>CUOTA ESTIMADA · ${q.term||60} MESES</small><strong>${money(d.payment)}<span>/mes</span></strong></div><div><small>FINANCIAMIENTO</small><strong>${d.bank}<span> ${d.bankRate.toFixed(2)}%</span></strong></div></div><p class="document-terms">Prototipo · Datos de ejemplo. Vigencia ilustrativa: 15 días. Imagen conceptual; no corresponde a una unidad específica. La simulación usa la tasa de ${d.bank}, ${d.bankRate.toFixed(2)}% anual; no constituye una oferta financiera. Disponibilidad, precios, impuestos y condiciones sujetos a validación en la implementación.</p><div class="document-footer">DISTRIBUIDORA DAVID PRESTIGE MOTORS<span>Una experiencia a su altura.</span></div></div></article>`,'document-modal')}
function reportModel(id){const v=vehicles.find(v=>v.id===id),rows=getSales(year,-1).filter(s=>s.model===v.model);openModal(`<div class="drawer-eyebrow">ORIGEN DEL REPORTE · ${year}</div><h2 class="drawer-title">${v.model}</h2><p class="drawer-subtitle">${rows.length} entregas · ${money(rows.reduce((a,x)=>a+x.price,0))} en ingresos</p><div class="report-records">${rows.map((r,i)=>`<div><span class="record-num">${String(i+1).padStart(2,'0')}</span><span><strong>${r.advisor}</strong><small>${months[r.month]} ${year} · ${r.bank}</small></span><strong>${money(r.price)}</strong></div>`).join('')}</div><p class="field-note">Registros sintéticos de demostración. Cada importe forma parte del total del reporte.</p>`)}
function downloadCSV(name,rows){const text='\uFEFF'+rows.map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Reporte descargado')}
function newTask(){openModal(`<div class="drawer-eyebrow">EL SIGUIENTE PASO</div><h2 class="drawer-title">Dale espacio a lo importante.</h2><form id="new-task-form" class="entry-form"><label>Actividad<input name="name" placeholder="Ej. Confirmar test drive" required maxlength="100"></label><label>Hora · 21 de septiembre 2026<input name="time" type="time" value="15:00" required></label><label>Cliente<select name="client">${state.clients.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label><label>Detalles<textarea name="desc" rows="4" placeholder="El objetivo de esta actividad"></textarea></label><button class="btn primary" type="submit">Añadir a mi agenda ${ic('calendar')}</button></form>`)}
function settings(){openModal(`<div class="drawer-eyebrow">TU ESPACIO DE TRABAJO</div><h2 class="drawer-title">Preferencias y acceso</h2><div class="detail-section"><h3>Perfil de demostración</h3><p class="settings-description">El selector de la barra lateral permite recorrer la experiencia de Gerencia, Ventas y Máster.</p><div class="permission-row"><span>${ic('shield')} Costos y margen</span><span class="tag ${canCost()?'green':''}">${canCost()?'Visible':'Oculto'}</span></div><div class="permission-row"><span>${ic('file')} Crear propuestas</span><span class="tag green">Disponible</span></div><div class="permission-row"><span>${ic('users')} Seguimiento de clientes</span><span class="tag green">Disponible</span></div></div><div class="detail-section"><h3>Tu sesión de prueba</h3><p class="settings-description">Los cambios de esta demo se conservan únicamente en este navegador. No hay envíos externos ni conexión a sistemas del cliente.</p><button class="btn secondary" data-action="reset-demo">Restablecer datos de ejemplo</button></div><div class="quiet-note">Este prototipo presenta los flujos y permisos visuales. La autenticación y los permisos reales requieren implementación de servidor.</div>`)}
document.addEventListener('click',e=>{
 const el=e.target.closest('button,[data-overlay]');if(!el)return;
 if(el.hasAttribute('data-overlay')&&e.target===el){closeModal();return}
 const a=el.dataset;
 if(a.client)openClient(a.client);
 if(a.vehicle)openVehicle(a.vehicle);
 if(a.quote)openQuote(a.quote);
 if(a.inventoryFilter){inventoryFilter=a.inventoryFilter;render()}
 if(a.quoteFilter){activeStage=a.quoteFilter;render()}
 if(a.newStage)newClient(a.newStage);
 if(a.reportModel)reportModel(a.reportModel);
 if(a.quoteStep){draft.step=+a.quoteStep;render()}
 if(a.selectVehicle){draft.vehicleId=a.selectVehicle;render()}
 if(a.paint){draft.paint=a.paint;render()}
 if(a.trim){draft.trim=a.trim;render()}
 if(a.wheel){draft.wheel=a.wheel;render()}
 if(a.bank){draft.bank=a.bank;draft.rate=(banks.find(b=>b.name===a.bank)||banks[0]).rate;render();toast('Financiamiento con '+a.bank)}
 if(a.selectClient){draft.clientId=a.selectClient;render()}
 if(a.quoteClient){const c=state.clients.find(c=>c.id===a.quoteClient);resetDraft(vehicles.find(v=>v.model===c.interest)?.id||'RS-086',c.id);closeModal();go('quote-builder')}
 if(a.logCall)logCall(a.logCall);
 if(a.editQuote){const q=state.quotes.find(q=>q.id===a.editQuote);draft={deposit:30,term:60,rate:7.25,paint:paints[0].name,trim:trims[0].name,wheel:wheels[0].name,...structuredClone(q),step:1};editingQuote=q.id;closeModal();go('quote-builder')}
 if(a.previewSaved){showDocument(state.quotes.find(q=>q.id===a.previewSaved),a.previewSaved)}
 if(a.approve&&canCost()){const q=state.quotes.find(q=>q.id===a.approve);q.status='Enviada';addNote(q.clientId,'Condiciones aprobadas',q.id+' revisada por Gerencia.');save();render();openQuote(q.id);toast('Condiciones aprobadas en esta demo')}
 if(a.complete){state.events=state.events.includes(a.complete)?state.events.filter(x=>x!==a.complete):[...state.events,a.complete];save();render()}
 if(a.agendaDay!==undefined){document.querySelectorAll('.day-chip').forEach(b=>b.classList.toggle('active',b===el));if(a.agendaDay==='0'){render()}else document.getElementById('agenda-events').innerHTML=`<div class="empty-state">${ic('calendar')}<h3>Espacio para nuevas conversaciones.</h3><p>No hay actividades para el ${21+Number(a.agendaDay)} de septiembre en este escenario.</p></div>`}
 if(a.prompt)assistantAnswer(a.prompt);
 const k=a.action;if(!k)return;
 if(k==='close')closeModal();
 if(k==='search')showSearch();
 if(k==='assistant')showAssistant();
 if(k==='settings')settings();
 if(k==='new-client')newClient();
 if(k==='new-task')newTask();
 if(k==='insight-quote'){const existing=state.quotes.find(q=>q.clientId==='c4');if(existing){openQuote(existing.id)}else{resetDraft('VL-032','c4');closeModal();go('quote-builder');toast('Velar y Camila vinculados a la propuesta')}}
 if(k.startsWith('vehicle-to-quote:')){resetDraft(k.split(':')[1]);closeModal();go('quote-builder')}
 if(k==='quote-next'){draft.step=Math.min(4,draft.step+1);render();document.querySelector('.quote-editor')?.scrollIntoView({behavior:'smooth',block:'start'})}
 if(k==='quote-back'){draft.step=Math.max(1,draft.step-1);render()}
 if(k==='preview-quote')showDocument();
 if(k==='print')window.print();
 if(k==='insights-close'){closeModal();go('insights')}
 if(k==='save-quote'){
 const d=calcQuote();const id=editingQuote||'DPM-'+String(Date.now()).slice(-7);const old=state.quotes.find(q=>q.id===id);const q={...structuredClone(draft),id,date:'2026-09-21',total:d.total,status:'Borrador',revision:old?(old.revision||1)+1:1};
 if(old)state.quotes=state.quotes.map(x=>x.id===id?q:x);else state.quotes.unshift(q);
 const client=state.clients.find(c=>c.id===draft.clientId);client.stage='Propuesta';client.value=d.net;client.interest=d.v.model;client.last='Ahora';
 addNote(client.id,old?'Propuesta actualizada':'Propuesta creada',id+' · '+d.v.model+' · '+money(d.total));save();go('quotes');openQuote(id);toast('Propuesta guardada en el historial del cliente');
 }
 if(k==='export-quotes')downloadCSV('Prestige-cotizaciones-demo.csv',[['Propuesta','Cliente','Vehículo','Importe neto','Impuesto demo','Total','Estado'],...state.quotes.map(q=>{const d=calcQuote(q);return[q.id,state.clients.find(c=>c.id===q.clientId).name,d.v.model,d.net.toFixed(2),d.tax.toFixed(2),d.total.toFixed(2),q.status]})]);
 if(k==='export-report')downloadCSV('Prestige-reporte-'+year+'-demo.csv',[['Año','Mes','Modelo','Asesor','Banco','Ingreso neto',...(canCost()?['Costo']:[])],...getSales(year,-1).map(r=>[r.year,months[r.month],r.model,r.advisor,r.bank,r.price.toFixed(2),...(canCost()?[r.cost.toFixed(2)]:[])])]);
 if(k==='approvals'){activeStage='Por aprobar';go('quotes')}
 if(k==='notifications')openModal(`<div class="drawer-eyebrow">CENTRO DE ATENCIÓN</div><h2 class="drawer-title">Lo que requiere tu mirada.</h2><div class="notification-list"><button data-action="approvals">${ic('shield')}<span><strong>Una propuesta por revisar</strong><small>Roberto Chen · Range Rover Autobiography</small></span>${ic('arrow')}</button><button data-action="insight-quote">${ic('spark')}<span><strong>Inventario con potencial</strong><small>Velar · 76 días · Cliente interesado</small></span>${ic('arrow')}</button><button data-client="c8">${ic('calendar')}<span><strong>Test drive de Lucía</strong><small>Hoy, 14:00 · Costa del Este</small></span>${ic('arrow')}</button></div>`);
 if(k==='reset-demo')openModal(`<div class="drawer-eyebrow">SESIÓN DE DEMOSTRACIÓN</div><h2 class="drawer-title">Volver al punto de partida.</h2><p class="settings-description">Se eliminarán las propuestas, clientes y actividades que creaste en este navegador durante la prueba. Los datos originales de ejemplo volverán a estar disponibles.</p><div class="drawer-actions">${button('Conservar mi sesión','close','secondary')}${button('Restablecer demo','confirm-reset','primary')}</div>`,'small-modal');
 if(k==='confirm-reset'){state=structuredClone(defaultState);save();closeModal();resetDraft();go('overview');toast('Datos de ejemplo restablecidos')}
 if(['approvals','agenda','pipeline','insights'].includes(k)&&document.querySelector('[data-overlay]'))closeModal();
});
