 if(a.accessory){draft.accessories=el.checked?[...new Set([...draft.accessories,a.accessory])]:draft.accessories.filter(x=>x!==a.accessory);el.closest('.accessory').classList.toggle('selected',el.checked);refreshSummary()}
 if(el.id==='term'){draft.term=Number(el.value);refreshSummary()}
